using System.Diagnostics;
using System.Text;

namespace NetInspector.Desktop;

internal static class MaintenanceRunner
{
    internal static string Quote(string text) => "'" + text.Replace("'", "''") + "'";
    // Elevated operations get fixed scripts generated by the application, never shell text from input boxes.
    internal static async Task<int> Run(string script, bool elevated, Action<string> report, CancellationToken ct)
    {
        ct.ThrowIfCancellationRequested();
        var folder = Path.Combine(Path.GetTempPath(), "NetInspector-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(folder);
        var log = Path.Combine(folder, "output.log");
        var stop = Path.Combine(folder, "cancel");
        var wrapper = "$ErrorActionPreference='Stop'; $cancelFile=" + Quote(stop) + "; $result=0; & { try { " + script +
            "\n } catch { Write-Output ('Falha: ' + $_); $script:result=1 } } *>&1 | ForEach-Object { $_.ToString() | Out-File -LiteralPath " + Quote(log) + " -Encoding utf8 -Append }; exit $result";
        var start = new ProcessStartInfo("powershell.exe") { UseShellExecute = elevated, CreateNoWindow = true, WindowStyle = ProcessWindowStyle.Hidden };
        if (elevated) start.Verb = "runas";
        foreach (var arg in new[] { "-NoProfile", "-NonInteractive", "-EncodedCommand", Convert.ToBase64String(Encoding.Unicode.GetBytes(wrapper)) }) start.ArgumentList.Add(arg);
        try
        {
            using var process = Process.Start(start) ?? throw new IOException("Não foi possível iniciar a ferramenta.");
            var offset = 0;
            void ReadOutput()
            {
                try
                {
                    if (!File.Exists(log)) return;
                    using var stream = new FileStream(log, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
                    using var reader = new StreamReader(stream, Encoding.UTF8);
                    var text = reader.ReadToEnd();
                    var end = text.LastIndexOf('\n') + 1;
                    if (end > offset) { report(text[offset..end].TrimEnd()); offset = end; }
                }
                catch (IOException) { }
            }
            var signaled = false;
            while (!process.HasExited)
            {
                if (ct.IsCancellationRequested && !signaled)
                {
                    File.WriteAllText(stop, "cancel"); signaled = true;
                    report("Cancelamento solicitado. A etapa atual pode precisar terminar; aguarde o resultado.");
                }
                ReadOutput(); await Task.Delay(250);
            }
            await process.WaitForExitAsync(); ReadOutput();
            return process.ExitCode;
        }
        finally
        {
            // Only the three known files in this invocation's directory are removed.
            try { File.Delete(log); File.Delete(stop); Directory.Delete(folder); } catch (IOException) { } catch (UnauthorizedAccessException) { }
        }
    }

    internal const string NativeFunction = """
        function Invoke-Native($exe, $arguments) {
            if (Test-Path -LiteralPath $cancelFile) { throw 'Cancelado antes de iniciar o comando.' }
            $psi = New-Object Diagnostics.ProcessStartInfo
            $psi.FileName=$exe; $psi.Arguments=$arguments; $psi.UseShellExecute=$false
            $psi.CreateNoWindow=$true; $psi.RedirectStandardOutput=$true; $psi.RedirectStandardError=$true
            $p=New-Object Diagnostics.Process; $p.StartInfo=$psi; $null=$p.Start()
            $out=$p.StandardOutput.ReadLineAsync(); $err=$p.StandardError.ReadLineAsync()
            while (-not $p.HasExited -or $null -ne $out -or $null -ne $err) {
                if ($null -ne $out -and $out.IsCompleted) {
                    $line=$out.GetAwaiter().GetResult()
                    if ($null -eq $line) { $out=$null } else { Write-Output $line; $out=$p.StandardOutput.ReadLineAsync() }
                }
                if ($null -ne $err -and $err.IsCompleted) {
                    $line=$err.GetAwaiter().GetResult()
                    if ($null -eq $line) { $err=$null } else { Write-Output $line; $err=$p.StandardError.ReadLineAsync() }
                }
                if (Test-Path -LiteralPath $cancelFile) { $p.Kill(); $p.WaitForExit(); throw 'Cancelado. Etapas já concluídas foram mantidas.' }
                Start-Sleep -Milliseconds 50
            }
            $p.WaitForExit()
            $code=$p.ExitCode; $p.Dispose()
            if ($code -ne 0) { throw ('Comando terminou com código ' + $code) }
        }
        """;

    internal const string WindowsCleanup = """
        Write-Output 'Abrindo a Limpeza de Disco do Windows. Selecione Instalações anteriores do Windows e confirme na janela do sistema. A remoção elimina a opção de voltar à versão anterior.'
        $p=Start-Process -FilePath "$env:windir\System32\cleanmgr.exe" -ArgumentList '/d', $env:SystemDrive -PassThru -Wait
        Write-Output ('Limpeza de Disco encerrada (código ' + $p.ExitCode + '). Confira os itens escolhidos; o encerramento não confirma a remoção de Windows.old.')
        """;
}
